// Process blocks and create comprehensive block metadata
const pageData = $('Get All Pages').item.json;
const blocks = $input.all();

const pageId = pageData.id.replace(/-/g, '');
const pageUrl = pageData.url || `https://www.notion.so/${pageId}`;

// Get page title
let pageTitle = 'Untitled';
if (pageData.properties?.Name?.title?.[0]?.plain_text) {
  pageTitle = pageData.properties.Name.title[0].plain_text;
} else if (pageData.properties?.title?.title?.[0]?.plain_text) {
  pageTitle = pageData.properties.title.title[0].plain_text;
}

const blockRecords = [];

for (const block of blocks) {
  const blockJson = block.json;
  const blockId = blockJson.id.replace(/-/g, '');
  const blockUrl = `https://www.notion.so/${pageId}#${blockId}`;

  const record = {
    page_id: pageData.id,
    page_title: pageTitle,
    page_url: pageUrl,
    block_id: blockJson.id,
    block_id_no_hyphens: blockId,
    block_url: blockUrl,
    block_type: blockJson.type,
    block_content: extractContent(blockJson),
    has_children: blockJson.has_children,
    created_time: blockJson.created_time,
    last_edited_time: blockJson.last_edited_time,
    indexed_at: new Date().toISOString()
  };

  blockRecords.push(record);
}

function extractContent(block) {
  const type = block.type;

  // Handle rich text blocks
  if (block[type]?.rich_text) {
    return block[type].rich_text
      .map(rt => rt.plain_text)
      .join('')
      .substring(0, 500); // Limit to 500 chars
  }

  // Handle different block types
  switch(type) {
    case 'heading_1':
    case 'heading_2':
    case 'heading_3':
      return block[type]?.rich_text?.map(rt => rt.plain_text).join('') || '';
    case 'table':
      return `Table: ${block[type]?.table_width || 0} columns`;
    case 'equation':
      return `Equation: ${block[type]?.expression || ''}`;
    case 'divider':
      return '---';
    case 'child_page':
      return `Child page: ${block[type]?.title || ''}`;
    case 'child_database':
      return `Database: ${block[type]?.title || ''}`;
    case 'code':
      const code = block[type]?.rich_text?.map(rt => rt.plain_text).join('') || '';
      return `Code (${block[type]?.language || 'plain'}): ${code.substring(0, 200)}`;
    default:
      return `${type} block`;
  }
}

return blockRecords.map(record => ({ json: record }));

// Extract block ID from URL
const body = $input.item.json.body;
const url = body.url;

if (!url || !url.includes('#')) {
  return { json: { error: 'Not a block URL' } };
}

// Extract block ID from anchor
const anchorMatch = url.match(/#([a-f0-9]{32})/);
if (!anchorMatch) {
  return { json: { error: 'Could not extract block ID' } };
}

const blockIdNoHyphens = anchorMatch[1];

return { json: { blockIdNoHyphens } };

// Format unfurl response for Notion
const blockData = $input.item.json;

if (!blockData || !blockData.block_url) {
  return {
    json: {
      type: "block_card",
      block_card: {
        title: { type: "text", text: "Block Not Found" },
        description: { type: "text", text: "This block could not be found in the index" },
        url: $('Extract Block ID').item.json.body.url
      }
    }
  };
}

const blockTypeLabel = blockData.block_type
  .split('_')
  .map(w => w.charAt(0).toUpperCase() + w.slice(1))
  .join(' ');

let description = `${blockTypeLabel}`;
if (blockData.block_content) {
  description += ` | ${blockData.block_content.substring(0, 100)}`;
  if (blockData.block_content.length > 100) {
    description += '...';
  }
}

return {
  json: {
    type: "block_card",
    block_card: {
      title: {
        type: "text",
        text: `${blockData.page_title} - ${blockTypeLabel}`
      },
      description: {
        type: "text",
        text: description
      },
      url: blockData.block_url
    }
  }
};
